#!/bin/bash
# Train-split evaluation.  No arguments.
#
# Same interface and scoring rules as the hidden test, on public-seed train
# scenes generated by eval/train/.  Runs every solver in scripts/methods/*.sh
# (all experiments in one call, opaque scene ids) and writes
# scoring/scores_train.json.  Inputs and outputs are kept under outputs/train/.

set -e

WORKSPACE_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$WORKSPACE_DIR"
export PYTHONPATH="$WORKSPACE_DIR:${PYTHONPATH:-}"
mkdir -p scoring

python -m eval.train.evaluate --scores scoring/scores_train.json
